// swift-tools-version:5.10
// RustBridge: local SPM package that exposes the generated UniFFI Swift
// bindings plus the Rust static library (XCFramework) to the app target.
//
// Checked in: Package.swift
// Generated by scripts/build-ios.sh (NOT checked in):
//   Sources/A0Platform/A0Platform.swift        (UniFFI 0.31, library mode)
//   Sources/A0Platform/include/*.h, module.modulemap
//   Frameworks/A0Platform.xcframework
//
// The xcframework Headers/ directory carries A0PlatformFFI.h and
// module.modulemap, so the binary target publishes the C module
// A0PlatformFFI that the generated Swift bindings import
// (see `#if canImport(A0PlatformFFI)`).
//
// No `unsafeFlags` here: SwiftPM rejects packages with unsafe build flags
// when they are consumed by an Xcode project.
import PackageDescription

let package = Package(
    name: "RustBridge",
    platforms: [.iOS(.v17)],
    products: [
        .library(name: "RustBridge", targets: ["A0Platform"])
    ],
    targets: [
        .binaryTarget(
            name: "A0PlatformFFI",
            path: "Frameworks/A0Platform.xcframework"
        ),
        .target(
            name: "A0Platform",
            dependencies: ["A0PlatformFFI"],
            path: "Sources/A0Platform",
            exclude: ["include"]
        )
    ]
)
